        self::assertSame('', (string) $request->getBody());
        self::assertSame(200, $result->rawResponse()?->status);
        self::assertSame($this->decoded('{"stage":"none","stage_changed_at":"2026-01-15T10:30:00Z","stage_changed_by":"stage_changed_by-value","monthly_spend_limit":"10.50","spend_limit":{"enabled":true,"limit":"10.50","spent":"10.50","reviews":1,"reserved":"10.50","currency":"currency-value","paused":true}}'), $result->toArray());
        self::assertSame('none', $result->stage);
    }

    public function testUpdateSettings(): void
    {
        $this->queueJson(200, '{"stage":"none","stage_changed_at":"2026-01-15T10:30:00Z","stage_changed_by":"stage_changed_by-value","monthly_spend_limit":"10.50","spend_limit":{"enabled":true,"limit":"10.50","spent":"10.50","reviews":1,"reserved":"10.50","currency":"currency-value","paused":true}}');

        $result = $this->client->investigator->updateSettings([
            'stage' => 'none',
            'monthly_spend_limit' => '10.50',
        ]);

        $request = $this->lastRequest();
        self::assertSame('PATCH', $request->getMethod());
        self::assertSame('verification.didit.me', $request->getUri()->getHost());
        self::assertSame('/v3/investigator/settings/', $request->getUri()->getPath());
        self::assertSame([], $this->queryParams($request));
        self::assertSame(self::API_KEY, $request->getHeaderLine('x-api-key'));
        self::assertSame('application/json', $request->getHeaderLine('Content-Type'));
        self::assertSame('{"stage":"none","monthly_spend_limit":"10.50"}', $this->canonicalBody($request));
        self::assertSame(200, $result->rawResponse()?->status);
        self::assertSame($this->decoded('{"stage":"none","stage_changed_at":"2026-01-15T10:30:00Z","stage_changed_by":"stage_changed_by-value","monthly_spend_limit":"10.50","spend_limit":{"enabled":true,"limit":"10.50","spent":"10.50","reviews":1,"reserved":"10.50","currency":"currency-value","paused":true}}'), $result->toArray());
        self::assertSame('none', $result->stage);
    }
